begin;
select set_config('request.jwt.claim.sub','f9200000-0000-0000-0000-000000000001',true);select set_config('request.jwt.claim.role','authenticated',true);
insert into branches(id,code,name) values('db100000-0000-0000-0000-000000000001','LROLE-A','Roles Logística ficticia A'),('db100000-0000-0000-0000-000000000002','LROLE-B','Roles Logística ficticia B');
insert into auth.users(id,email) values('db200000-0000-0000-0000-000000000001','role-trip-one@example.invalid'),('db200000-0000-0000-0000-000000000002','role-trip-two@example.invalid'),('db200000-0000-0000-0000-000000000003','role-trip-review@example.invalid'),('db200000-0000-0000-0000-000000000004','role-trip-finance@example.invalid');
insert into profiles(id,full_name,branch_id,active) select v.id,v.name,'db100000-0000-0000-0000-000000000001',true from(values('db200000-0000-0000-0000-000000000001'::uuid,'Colaborador ficticio 1'),('db200000-0000-0000-0000-000000000002'::uuid,'Colaborador ficticio 2'),('db200000-0000-0000-0000-000000000003'::uuid,'Supervisor ficticio'),('db200000-0000-0000-0000-000000000004'::uuid,'Finanzas ficticias'))v(id,name);
insert into user_roles(user_id,role_id,branch_id) select v.id,r.id,'db100000-0000-0000-0000-000000000001' from(values('db200000-0000-0000-0000-000000000001'::uuid,'LOGISTICA_CONDUCTOR'),('db200000-0000-0000-0000-000000000002'::uuid,'LOGISTICA_CONDUCTOR'),('db200000-0000-0000-0000-000000000003'::uuid,'LOGISTICA_SUPERVISOR'),('db200000-0000-0000-0000-000000000004'::uuid,'FINANZAS'))v(id,code)join roles r on r.code=v.code;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create function pg_temp.denied(stmt text,label text) returns void language plpgsql as $$begin begin execute stmt;exception when others then raise notice 'PASS %',label;return;end;raise exception 'FAIL unexpectedly allowed %',label;end$$;
create function pg_temp.claim(dep text,arr text,key uuid default gen_random_uuid()) returns jsonb language sql as $$select jsonb_build_object('branch_id','db100000-0000-0000-0000-000000000001','origin','HemoCura ficticio','destination','Centro ficticio','purpose','ENTREGA','departure_local',dep,'arrival_local',arr,'request_id',key)$$;
set local role authenticated;select set_config('request.jwt.claim.sub','db200000-0000-0000-0000-000000000001',true);
select pg_temp.ok(has_permission('TRIPS_WRITE') and not has_permission('ACCESS_ADMIN') and not has_permission('TRIPS_REVIEW'),'logistics role can submit but cannot administer or approve');
select pg_temp.ok((select count(*)=1 from vw_logistics_trip_branches),'worker branch selector excludes unauthorized branches');
select pg_temp.denied($q$select logistics_trip_action('CREATE',pg_temp.claim('2026-10-12T09:00','2026-10-12T17:00'))$q$,'weekday trip within working hours is rejected');
select pg_temp.ok(logistics_trip_schedule('2026-10-12 18:00-04')->>'classification'='DENTRO_DE_JORNADA','exact weekday end is within authorized shift');
select pg_temp.ok(logistics_trip_schedule('2026-10-10 12:00-04')->>'classification'='DENTRO_DE_JORNADA' and logistics_trip_schedule('2026-10-10 12:01-04')->>'classification'='DESPUES_DE_JORNADA','Saturday noon boundary is correct');
select pg_temp.ok(logistics_trip_schedule('2026-10-11 10:00-04')->>'classification'='DIA_NO_LABORABLE','Sunday has no regular working shift');
select pg_temp.denied($q$select logistics_trip_action('CREATE',pg_temp.claim('2099-10-12T17:00','2099-10-12T19:00'))$q$,'unfinished future trip is rejected');
select logistics_trip_action('CREATE',pg_temp.claim('2026-10-12T17:00','2026-10-12T19:00','db300000-0000-0000-0000-000000000001'));
select logistics_trip_action('CREATE',pg_temp.claim('2026-10-12T17:00','2026-10-12T19:00','db300000-0000-0000-0000-000000000001'));
select pg_temp.ok((select count(*)=1 and bool_and(amount is null and status='ENVIADO' and worker_id=auth.uid() and worker_name='Colaborador ficticio 1') from logistics_trips where branch_id='db100000-0000-0000-0000-000000000001'),'retry is idempotent and stamps real worker without promising incentive');
select pg_temp.denied($q$select logistics_trip_action('CREATE',pg_temp.claim('2026-10-12T18:00','2026-10-12T20:00'))$q$,'overlapping duplicate claim is rejected');
select pg_temp.denied($q$select logistics_trip_action('CREATE',pg_temp.claim('2026-10-12T17:00','2026-10-12T19:00','db300000-0000-0000-0000-000000000001')||'{"origin":"Changed"}')$q$,'same request key cannot be reused with changed payload');
select pg_temp.denied($q$select logistics_trip_action('CREATE',pg_temp.claim('2026-10-13T17:00','2026-10-13T19:00')||'{"branch_id":"db100000-0000-0000-0000-000000000002"}')$q$,'worker cannot claim another branch');
select pg_temp.denied($q$update logistics_trips set status='APROBADO',amount=500,review_note='Autorizado'$q$,'direct self approval is rejected');
select pg_temp.denied($q$update logistics_trips set worker_id='db200000-0000-0000-0000-000000000002'$q$,'worker identity cannot be changed');
select pg_temp.denied($q$delete from logistics_trip_history$q$,'worker cannot delete incentive audit');
select set_config('request.jwt.claim.sub','db200000-0000-0000-0000-000000000002',true);
select pg_temp.ok((select count(*)=0 from logistics_trips where branch_id='db100000-0000-0000-0000-000000000001') and (select count(*)=0 from logistics_trip_history),'workers cannot read other worker claims or history');
select logistics_trip_action('CREATE',pg_temp.claim('2026-10-10T11:00','2026-10-10T13:00'));
select set_config('request.jwt.claim.sub','db200000-0000-0000-0000-000000000003',true);
select logistics_trip_action('CREATE',pg_temp.claim('2026-10-14T18:30','2026-10-14T20:00'));
select pg_temp.denied($q$select logistics_trip_action('APPROVE',(select jsonb_build_object('id',id,'revision',revision,'amount',500,'review_note','Autorrevisión') from logistics_trips where branch_id='db100000-0000-0000-0000-000000000001' and worker_id=auth.uid()))$q$,'supervisor cannot approve their own trip even with review permission');
select pg_temp.denied($q$select logistics_trip_action('APPROVE',(select jsonb_build_object('id',id,'revision',revision,'amount',0,'review_note','Prueba') from logistics_trips where branch_id='db100000-0000-0000-0000-000000000001' and request_id='db300000-0000-0000-0000-000000000001'))$q$,'incentive must be positive and authorized');
select pg_temp.denied($q$update logistics_trips set schedule_snapshot='{}',status='APROBADO',amount=500,review_note='Prueba' where request_id='db300000-0000-0000-0000-000000000001'$q$,'reviewer cannot replace preserved working schedule');
select logistics_trip_action('RETURN',(select jsonb_build_object('id',id,'revision',revision,'review_note','Añadir referencia de entrega') from logistics_trips where branch_id='db100000-0000-0000-0000-000000000001' and request_id='db300000-0000-0000-0000-000000000001'));
select set_config('request.jwt.claim.sub','db200000-0000-0000-0000-000000000001',true);
select logistics_trip_action('RESUBMIT',(select pg_temp.claim('2026-10-12T17:00','2026-10-12T19:00')||jsonb_build_object('id',id,'revision',revision,'delivery_reference','ENTREGA-FICTICIA') from logistics_trips where branch_id='db100000-0000-0000-0000-000000000001' and request_id='db300000-0000-0000-0000-000000000001'));
select pg_temp.ok((select status='ENVIADO' and revision=3 and reviewed_by is null from logistics_trips where branch_id='db100000-0000-0000-0000-000000000001'),'correction resubmits with fresh review and audit revision');
select set_config('request.jwt.claim.sub','db200000-0000-0000-0000-000000000003',true);
select logistics_trip_action('APPROVE',(select jsonb_build_object('id',id,'revision',revision,'amount',500,'review_note','Entrega verificada y tarifa autorizada','scheduled_end_local','2026-10-12T01:00') from logistics_trips where branch_id='db100000-0000-0000-0000-000000000001' and request_id='db300000-0000-0000-0000-000000000001'));
select pg_temp.ok((select amount=500 and reviewed_by=auth.uid() and scheduled_end_at='2026-10-12 18:00-04'::timestamptz from logistics_trips where branch_id='db100000-0000-0000-0000-000000000001' and request_id='db300000-0000-0000-0000-000000000001'),'review stamps actual supervisor and authorized schedule rather than supplied fake hours');
select pg_temp.denied($q$select logistics_trip_action('APPROVE',(select jsonb_build_object('id',id,'revision',1,'amount',900,'review_note','Prueba') from logistics_trips where branch_id='db100000-0000-0000-0000-000000000001' and request_id='db300000-0000-0000-0000-000000000001'))$q$,'stale review cannot overwrite approved incentive');
select pg_temp.denied($q$update logistics_trips set origin='Falso',status='DEVUELTO',review_note='Prueba' where request_id='db300000-0000-0000-0000-000000000001'$q$,'supervisor cannot alter reported trip facts');
select set_config('request.jwt.claim.sub','db200000-0000-0000-0000-000000000004',true);
select pg_temp.denied($q$select logistics_trip_action('SETTLE',jsonb_build_object('branch_id','db100000-0000-0000-0000-000000000001','payroll_reference','BATCH-INVALIDO','trips',(select jsonb_agg(jsonb_build_object('id',id,'revision',revision)) from logistics_trips where branch_id='db100000-0000-0000-0000-000000000001')))$q$,'mixed pending and approved settlement batch is rejected atomically');
select pg_temp.ok((select count(*)=0 from logistics_trips where branch_id='db100000-0000-0000-0000-000000000001' and status='LIQUIDADO'),'invalid settlement batch leaves all awards unchanged');
select logistics_trip_action('SETTLE',jsonb_build_object('branch_id','db100000-0000-0000-0000-000000000001','payroll_reference','NOMINA-FICTICIA','trips',(select jsonb_agg(jsonb_build_object('id',id,'revision',revision)) from logistics_trips where branch_id='db100000-0000-0000-0000-000000000001' and status='APROBADO')));
select pg_temp.ok((select status='LIQUIDADO' and amount=500 and settled_by=auth.uid() and payroll_reference='NOMINA-FICTICIA' from logistics_trips where branch_id='db100000-0000-0000-0000-000000000001' and request_id='db300000-0000-0000-0000-000000000001'),'finance records approved amount and payroll reference without modifying the award');
select pg_temp.denied($q$update logistics_trips set amount=900 where status='LIQUIDADO'$q$,'settled incentive is immutable');
select pg_temp.denied($q$select logistics_trip_action('SETTLE',jsonb_build_object('branch_id','db100000-0000-0000-0000-000000000001','payroll_reference','DUP','trips',(select jsonb_agg(jsonb_build_object('id',id,'revision',revision)) from logistics_trips where branch_id='db100000-0000-0000-0000-000000000001' and status='LIQUIDADO')))$q$,'same award cannot be settled twice');
select pg_temp.denied($q$select logistics_trip_action('APPROVE',(select jsonb_build_object('id',id,'revision',revision,'amount',500,'review_note','No autorizado') from logistics_trips where branch_id='db100000-0000-0000-0000-000000000001' and status='ENVIADO' limit 1))$q$,'finance cannot independently approve unreviewed trips');
reset role;
update profiles set active=false where id='db200000-0000-0000-0000-000000000001';set local role authenticated;select set_config('request.jwt.claim.sub','db200000-0000-0000-0000-000000000001',true);
select pg_temp.denied($q$select logistics_trip_action('CREATE',pg_temp.claim('2026-10-13T17:00','2026-10-13T19:00'))$q$,'inactive worker cannot submit');
reset role;set local role anon;
select pg_temp.denied($q$select logistics_trip_action('CREATE','{}')$q$,'anonymous cannot submit incentive claims');
reset role;
select set_config('request.jwt.claim.sub','f9200000-0000-0000-0000-000000000001',true);
insert into auth.users(id,email) values('db200000-0000-0000-0000-000000000005','role-trip-consultation@example.invalid');
insert into profiles(id,full_name,branch_id,active) values('db200000-0000-0000-0000-000000000005','Consulta ficticia','db100000-0000-0000-0000-000000000001',true);
insert into user_roles(user_id,role_id,branch_id) select 'db200000-0000-0000-0000-000000000005',id,'db100000-0000-0000-0000-000000000001' from roles where code='LOGISTICA_CONSULTA';
set local role authenticated;select set_config('request.jwt.claim.sub','db200000-0000-0000-0000-000000000005',true);
select pg_temp.ok(has_permission('TRIPS_READ_ALL') and not has_permission('TRIPS_WRITE') and not has_permission('TRIPS_REVIEW') and not has_permission('TRIPS_SETTLE') and not has_permission('ACCESS_ADMIN'),'team consultation receives read-only permissions');
select pg_temp.ok((select count(*)>=3 from logistics_trips where branch_id='db100000-0000-0000-0000-000000000001'),'team consultation can read other workers in assigned branch');
select pg_temp.ok((select count(*)>0 from logistics_trip_history),'team consultation can read visible trip history');
select pg_temp.ok((select count(*)=2 from vw_my_module_access where enabled),'team consultation exposes exactly two windows');
select pg_temp.ok(not logistics_access('db100000-0000-0000-0000-000000000002'),'consultation cannot access unassigned branch');
select pg_temp.denied($q$select logistics_trip_action('CREATE',pg_temp.claim('2026-10-12T17:00','2026-10-12T19:00'))$q$,'consultation cannot submit trips');
select pg_temp.denied($q$select logistics_trip_action('APPROVE',(select jsonb_build_object('id',id,'revision',revision,'amount',500,'review_note','No autorizado') from logistics_trips where branch_id='db100000-0000-0000-0000-000000000001' and status='ENVIADO' limit 1))$q$,'consultation cannot approve incentives');
with changed as(update logistics_trips set note='No autorizado' returning id) select pg_temp.ok((select count(*)=0 from changed),'consultation cannot update trips directly');
reset role;
select pg_temp.ok(not exists(select 1 from role_permissions rp join roles r on r.id=rp.role_id where r.code in ('LOGISTICA_CONDUCTOR','LOGISTICA_SUPERVISOR','LOGISTICA_CONSULTA') and rp.permission_code in ('TRIPS_SETTLE','ACCESS_ADMIN')),'new logistics roles do not receive Finance or user administration');
rollback;
